// B · Koordinator: validasi perintah & tetapkan aturan baku. Perintah yang menyimpang DITOLAK di sini.
const b = $input.first().json.body || $input.first().json;
const topik = String(b.topik || '').trim();
const pelanggaran = [];
if (topik.length < 3) pelanggaran.push('topik kosong/terlalu pendek');
if (/nomor hp|no hp|whatsapp pribadi|alamat rumah pribadi|ktp|nik/i.test(topik)) pelanggaran.push('topik meminta data pribadi (dilarang)');
if (/@rumah_murah_solo/i.test(topik)) pelanggaran.push('akun RMS tidak boleh dipakai agen');
const upload = ['hari','minggu','bulan','semua'].includes(b.upload) ? b.upload : (/terbaru|baru|latest/i.test(topik) ? 'minggu' : 'bulan');
const jumlah = Math.min(3, Math.max(1, Number(b.jumlah) || 2));
return [{ json: { topik, upload, jumlah, pelanggaran, diterima_pada: new Date().toISOString(), sop_versi: '1.1' } }];

// Pemeriksa alur baku: setiap paket WAJIB punya bidang ini. Yang kurang ditandai, tidak ditebak, tidak dilewati.
const WAJIB = ['link','judul','kanal','status','bagian_terpilih','kekurangan'];
return $input.all().map(i => {
  const p = i.json;
  const hilang = WAJIB.filter(k => p[k] === undefined || p[k] === null);
  const bagian = Array.isArray(p.bagian_terpilih) ? p.bagian_terpilih : [];
  const tanpaKonteks = bagian.filter(b => !b.kutipan).length;
  const tanpaGambar = bagian.filter(b => !b.screenshot).length;
  const penyimpangan = [];
  if (hilang.length) penyimpangan.push('bidang wajib hilang: ' + hilang.join(', '));
  if (p.transkrip && bagian.length === 0) penyimpangan.push('ada transkrip tapi tidak ada bagian terpilih');
  if (tanpaKonteks) penyimpangan.push(tanpaKonteks + ' bagian tanpa kutipan');
  if (tanpaGambar) penyimpangan.push(tanpaGambar + ' bagian tanpa gambar');
  if (!['LENGKAP','PERLU_LIHAT_PELAN','KURANG_BAHAN'].includes(p.status)) penyimpangan.push('status di luar daftar baku: ' + p.status);
  return { json: { ...p, penyimpangan, lolos_pemeriksa: penyimpangan.length === 0 } };
});

// Gabungkan hasil robot ke paket; tentukan K. MATA WAJIB: tanpa mata tidak pernah LENGKAP.
const paket = $('Pemeriksa alur baku').all();
return $input.all().map((i, idx) => {
  const p = paket[idx] ? paket[idx].json : {};
  const r = i.json || {};
  const robot = r.error ? { mode: 'gagal', galat: r.error } : r;
  const mataAktif = robot.mode === 'mata' && robot.semua_dilihat === true;
  const belum = (robot.items||[]).filter(x => x.cocok !== 'ya').length;
  const konteks_jelas = p.status === 'LENGKAP' && mataAktif && belum === 0 && p.lolos_pemeriksa;
  const penyimpangan = [...(p.penyimpangan||[])];
  if (!mataAktif) penyimpangan.push('MATA TIDAK AKTIF: robot mode ' + (robot.mode||'?') + (robot.galat_mata ? ' (' + robot.galat_mata + ')' : '') + ' → paket tidak boleh LENGKAP');
  return { json: { ...p, penyimpangan, robot_pencocok: robot, mata_aktif: mataAktif, konteks_jelas, konteks_visual: (robot.items||[]).map(x => `[${x.clock}] ${x.deskripsi_gambar} (cocok: ${x.cocok})`).join('\n'), ringkasan_visual: robot.ringkasan || null } };
});

// M–P · Lihat pelan / tandai. TIDAK MENEBAK. Bagian yang belum jelas jadi tugas 'lihat pelan' untuk Hermes/Claude Pekerja.
return $input.all().map(i => {
  const p = i.json;
  const tugas = (p.perlu_lihat_pelan || []).map(x => `${x.waktu} → ${x.link} (${x.alasan})`);
  const dariRobot = (p.robot_pencocok?.items||[]).filter(x => x.cocok !== 'ya').map(x => `${x.clock} → gambar ${x.cocok}: ${x.deskripsi_gambar}`);
  return { json: { ...p, tindak_lanjut: (tugas.length || dariRobot.length) ? 'LIHAT_PELAN' : 'TANDAI_KURANG', tugas_lihat_pelan: [...tugas, ...dariRobot], status: p.transkrip ? 'PERLU_LIHAT_PELAN' : 'KURANG_BAHAN', catatan_konteks: (p.catatan_konteks||'') + ' | Bagian belum jelas ditandai, tidak ditebak.' } };
});

// L · Kumpulkan paket bahan (format serah-terima baku). Gambar berat TIDAK ikut: hanya deskripsi + waktu + link detik.
return $input.all().map(i => {
  const p = i.json;
  return { json: {
    perintah: p.perintah, link: p.link, judul: p.judul, kanal: p.kanal,
    tanggal_unggah: p.tanggal_unggah_perkiraan || p.tanggal_unggah_teks,
    transkrip: p.transkrip,
    bagian_terpilih: (p.bagian_terpilih||[]).map(b => ({ start: b.start, clock: b.clock, kutipan: b.kutipan, konteks_sebelum: b.konteks_sebelum, konteks_sesudah: b.konteks_sesudah, link_detik: b.link_detik, screenshot: b.screenshot ? { waktu: b.screenshot.waktu, tepat: b.screenshot.tepat, src: b.screenshot.src } : null })),
    konteks_visual: p.konteks_visual, ringkasan_visual: p.ringkasan_visual, mode_robot: p.robot_pencocok?.mode, mata_aktif: p.mata_aktif === true,
    catatan_konteks: p.catatan_konteks, status: p.status, kekurangan: p.kekurangan || [], penyimpangan: p.penyimpangan || [], tugas_lihat_pelan: p.tugas_lihat_pelan || [],
    sop_versi: '1.2', diproses_n8n: new Date().toISOString()
  } };
});

// Perintah ditolak: catat alasannya, jangan diproses.
const p = $input.first().json;
return [{ json: { ditolak: true, topik: p.topik, alasan: p.pelanggaran, pesan: 'Perintah menyimpang dari aturan Teliksandi dan tidak dijalankan.' } }];

// L2 · Perakit paket GPT (KUNCI). Teks untuk GPT dirakit di sini, dengan urutan tetap:
// 1 perintah → 2 sumber → 3 momen penting → 4 KONTEKS VISUAL (hasil mata) → 5 transkrip → 6 aturan.
// Tanpa konteks visual yang sah, bidang untuk_gpt TIDAK dibuat dan paket ditandai.
return $input.all().map(i => {
  const p = i.json;
  const bagian = Array.isArray(p.bagian_terpilih) ? p.bagian_terpilih : [];
  const momen = bagian.map(b => `[${b.clock}] ${b.kutipan} ${b.link_detik||''}`).join('\n');
  const mataSah = p.mata_aktif === true && (p.konteks_visual||'').trim().length > 0;
  const penyimpangan = [...(p.penyimpangan||[])];
  if (!mataSah) penyimpangan.push('PAKET GPT TIDAK DIRAKIT: konteks visual dari mata belum ada');
  const untuk_gpt = mataSah ? [
    'Analisa transkrip video ini secara menyeluruh. Buat: ringkasan eksekutif, poin penting, klaim utama, angka/fakta, entitas, insight bisnis, peluang, risiko, hal yang perlu diverifikasi, kesimpulan praktis. Bedakan fakta, opini, spekulasi. Jangan mengarang bagian yang hilang.',
    '', `Sumber video: ${p.link}`, `Judul: ${p.judul} · Kanal: ${p.kanal} · Unggah: ${p.tanggal_unggah||'-'}`,
    '', 'MOMEN PENTING:', momen || '(tidak ada)',
    '', 'KONTEKS VISUAL (hasil Robot Pencocok, mata aktif):', p.konteks_visual, `Ringkasan visual: ${p.ringkasan_visual||'-'}`,
    'Gunakan konteks visual ini saat menganalisis. Gambar yang "cocok: sebagian/tidak" berarti ucapan dan tampilan tidak sepenuhnya sejalan; sebutkan itu. Jangan menebak isi gambar di luar deskripsi.',
    '', 'TRANSKRIP:', p.transkrip || '(tidak ada transkrip)',
    '', `Status bahan: ${p.status}. Kekurangan: ${(p.kekurangan||[]).join('; ')||'-'}`
  ].join('\n') : null;
  return { json: { ...p, penyimpangan, untuk_gpt, paket_gpt_sah: mataSah, rakit_versi: '1.0' } };
});
